import { test } from "node:test";
import assert from "node:assert/strict";
import { teamsIdentifier, buildCustomCallingContext, resourceAccountFrom, voipKey, readVoipHeader, describeTransferError, describeTransferResult } from "../src/handoff.mjs";
import { AGENT_TOOLS, buildInstructions, localeLanguage } from "../src/agent.mjs";
import { HoursPolicy, Catalog } from "../src/policy.mjs";

test("sales queue is addressed as a Teams app", () => { assert.deepEqual(teamsIdentifier({ type:"callQueue", objectId:"queue" }), { teamsAppId:"queue", cloud:"public" }); });
test("missing Teams object id fails loudly", () => { assert.throws(()=>teamsIdentifier({ type:"callQueue" }),/objectId/); });
test("handoff context becomes VoIP headers with CallTopic <= 48 chars", () => { const headers=buildCustomCallingContext({ sessionId:"s", callTopic:"x".repeat(80), callContext:"needs bolts", routeId:"sales", afterHours:false }); assert.ok(headers.every(h=>h.kind==="voip")); assert.equal(headers.find(h=>h.key==="CallDetails-CallTopic").value.length,48); assert.equal(headers.find(h=>h.key==="CallDetails-RouteId").value,"sales"); });
test("absent handoff fields are omitted", () => { const keys=buildCustomCallingContext({ sessionId:"s", callTopic:"Sales inquiry" }).map(h=>h.key); assert.deepEqual(keys,["CallDetails-SessionId","CallDetails-CallTopic"]); });
test("VoIP header keys are letters, digits and hyphens only, because ACS rejects '.' and '_'", () => { const keys=buildCustomCallingContext({ sessionId:"s", callTopic:"Sales inquiry", callContext:"needs bolts", routeId:"sales", afterHours:true }).map(h=>h.key); assert.deepEqual(keys,["CallDetails-SessionId","CallDetails-CallTopic","CallDetails-CallContext","CallDetails-RouteId","CallDetails-AfterHours"]); for(const key of keys) assert.match(key,/^[A-Za-z0-9-]{1,64}$/); assert.equal(voipKey("CallDetails.Queue_Overflow"),"CallDetails-Queue-Overflow"); });
test("readVoipHeader reads back the headers buildCustomCallingContext sends", () => { const voipHeaders=Object.fromEntries(buildCustomCallingContext({ sessionId:"session-1", callTopic:"Industrial fasteners", callContext:"12000 bolts, this week", routeId:"sales", afterHours:true }).map(h=>[h.key,h.value])); const customContext={ voipHeaders }; assert.equal(readVoipHeader(customContext,"CallDetails.SessionId"),"session-1"); assert.equal(readVoipHeader(customContext,"CallDetails.CallTopic"),"Industrial fasteners"); assert.equal(readVoipHeader(customContext,"CallDetails.CallContext"),"12000 bolts, this week"); assert.equal(readVoipHeader(customContext,"CallDetails.AfterHours"),"true"); assert.equal(readVoipHeader(customContext,"CallDetails.QueueOverflow"),null); assert.equal(readVoipHeader(undefined,"CallDetails.SessionId"),null); });
test("transfer failures become one audit line", () => { const rejected=Object.assign(new Error("Invalid request"),{ statusCode:400, details:{ error:{ message:"Invalid request", details:[{ message:"Invalid CustomCallingContext in request, one or more provided voip headers with invalid key.", target:"CustomCallingContext" }] } } }); assert.equal(describeTransferError(rejected),"400 Invalid CustomCallingContext in request, one or more provided voip headers with invalid key."); assert.equal(describeTransferError(new Error("no call connection to transfer")),"no call connection to transfer"); assert.equal(describeTransferResult({ code:480, subCode:10140, message:"Temporarily Unavailable" }),"480/10140 Temporarily Unavailable"); assert.equal(describeTransferResult(undefined),"transfer failed"); });
test("TPE resource account is parsed from raw id", () => { assert.equal(resourceAccountFrom({ rawId:"28:orgid:cc123456-5678-5678-1234-ccc123456789" }),"cc123456-5678-5678-1234-ccc123456789"); assert.equal(resourceAccountFrom({ rawId:"4:+14255550193" }),null); });
test("agent tool surface has only server-owned tools", () => { assert.deepEqual(AGENT_TOOLS.map(t=>t.name).sort(),["classify_non_sales","end_call","lookup_catalog","save_lead"]); assert.ok(!JSON.stringify(AGENT_TOOLS).match(/score|owner|teamsAppId|phoneNumber/)); });
test("instructions disclose assistant and forbid prices, stock, and budget", () => { const instructions=buildInstructions({ hours:HoursPolicy.load("./config/hours.json"), catalog:Catalog.load("./config/catalog.json") },"en-US"); assert.match(instructions,/automated assistant/i); assert.match(instructions,/Never ask for budget/i); assert.match(instructions,/Never quote prices, stock/i); assert.doesNotMatch(instructions,/00000000-0000/); });
test("locale helper returns Voice Live transcription code", () => { assert.deepEqual(localeLanguage("fr-FR"), { locale:"fr-FR", code:"fr", label:"French (France)" }); });
